const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
return [{ json: { prefijo } }];

const j = (n) => $(n).first().json;
const r1 = j('CA86P_Revisar_1'), r2 = j('CA86P_Revisar_2'), r3 = j('CA86P_Revisar_3'), r4 = j('CA86P_Revisar_4');
const est = j('CA86P_Estado'), prep = j('CA86P_Preparar'), lim = j('CA86P_Limpiar');
let r5 = null; try { r5 = j('CA86P_Revisar_5'); } catch (e) { r5 = null; }
const pf = (ok) => (ok ? 'PASA' : 'FALLA');
const casos = [
  { caso: 'C1 2 errores seguidos: no corta', esperado: '0 cortes', resultado: pf(r1.estado === 'revisado' && r1.cortes === 0), detalle: JSON.stringify({ estado: r1.estado, cortes: r1.cortes }) },
  { caso: 'C2 error, error, ok, error, error: la racha se reinicia, no corta', esperado: '0 cortes', resultado: pf(r2.cortes === 0), detalle: JSON.stringify({ cortes: r2.cortes }) },
  { caso: 'C3 3 errores seguidos: corta el flujo 8.7', esperado: '1 corte y 8.7 apagado', resultado: pf(r3.cortes === 1 && r3.acciones[0].o_objeto === '8.7 Reporte semanal' && est.activo === false), detalle: JSON.stringify({ cortes: r3.cortes, acciones: r3.acciones, activo_8_7: est.activo }) },
  { caso: 'C4 motivo, responsable y errores registrados', esperado: 'Cortacircuitos: 3 errores seguidos / Monitoreo (cortacircuitos) / 3', resultado: pf(est.motivo === 'Cortacircuitos: 3 errores seguidos' && est.por === 'Monitoreo (cortacircuitos)' && Number(est.errores) === 3), detalle: JSON.stringify({ motivo: est.motivo, por: est.por, errores: est.errores }) },
  { caso: 'C5 deja auditoría, incidente y alerta (una de cada una; la alerta de prueba nace enviada)', esperado: '1 / 1 / 1 / enviada', resultado: pf(Number(est.auditorias) === 1 && Number(est.incidentes) === 1 && Number(est.alertas) === 1 && est.alertas_enviadas === true), detalle: JSON.stringify({ auditorias: est.auditorias, incidentes: est.incidentes, alertas: est.alertas, alertas_enviadas: est.alertas_enviadas }) },
  { caso: 'C6 repetir la revisión no duplica', esperado: '0 cortes', resultado: pf(r4.cortes === 0), detalle: JSON.stringify({ cortes: r4.cortes }) },
  { caso: 'C7 con el monitoreo apagado no revisa nada (falla segura)', esperado: 'estado apagado', resultado: r5 ? pf(r5.estado === 'apagado' && r5.hubo_acciones === false) : 'OMITIDO', detalle: r5 ? JSON.stringify({ estado: r5.estado }) : 'El monitoreo real está encendido: no se corre una revisión real desde la prueba' },
  { caso: 'C8 el interruptor 8.7 queda como estaba', esperado: JSON.stringify({ activo: prep.prev_activo, motivo: prep.prev_motivo }), resultado: pf(lim.activo === prep.prev_activo && lim.motivo === prep.prev_motivo && lim.cambiado_por === prep.prev_por), detalle: JSON.stringify({ activo: lim.activo, por: lim.cambiado_por, motivo: lim.motivo }) },
];
return casos.map((c) => ({ json: c }));
